from pathlib import Path

prompts = Path('src/ai_engine/prompts.py')
text = prompts.read_text(encoding='utf-8')
start = text.index('def build_live_diagnostic_probe_prompt(')
new_func = '''def build_live_diagnostic_probe_prompt(*, task_number: int, operation_index: int, skill_id: str, fields: dict[str, object], previous_prompts: list[str] | None = None) -> str:\n    \"\"\"Generate wording inside a teacher-authored EGE-like probe family.\"\"\"\n    previous = \"\\n\".join(f\"- {item}\" for item in (previous_prompts or []))\n    key = (task_number, operation_index)\n    placeholders_by_operation = {\n        (5, 0): (\"source_number\", \"source_system\", \"target_system\"), (5, 1): (\"n\",),\n        (5, 2): (\"binary\", \"suffix\"), (5, 3): (\"start\", \"limit\", \"expression\", \"boundary\"),\n        (14, 0): (\"n\", \"base\"), (14, 1): (\"digit\", \"value\"),\n        (14, 2): (\"remainders\", \"last_quotient\"),\n        (27, 0): (\"points\", \"within_distance\", \"between_min\"),\n        (27, 1): (\"sums\",), (27, 2): (\"labels\", \"target\"), (27, 3): (\"distances\",),\n    }\n    families = {\n        (5, 0): \"Короткая задача на перевод одного числа между десятичной и двоичной системами. Проси только результат.\",\n        (5, 1): \"Дай N и спроси, какая ветка выбирается по последнему биту двоичной записи. Не проси выполнять весь алгоритм.\",\n        (5, 2): \"Дай готовую двоичную строку и суффикс. Попроси записать строку после приписывания суффикса справа.\",\n        (5, 3): \"Дай диапазон целых N и неравенство. Попроси найти наибольшее подходящее N.\",\n        (14, 0): \"Дано десятичное число и основание. Спроси только остаток от первого деления, ответ обычным десятичным числом.\",\n        (14, 1): \"Дай цифру системы счисления и её числовое значение. Спроси, чётно ли числовое значение; ответ да/нет.\",\n        (14, 2): \"Дай остатки в порядке получения и последнее ненулевое частное. Попроси записать итоговую запись числа. Не спрашивай число элементов или разрядов.\",\n        (27, 0): \"Даны четыре точки, внутригрупповое расстояние и нижняя граница межгруппового расстояния. Попроси определить число явно разделённых кластеров.\",\n        (27, 1): \"Дай суммы расстояний для A, B, C. Попроси выбрать медоид как точку с минимальной суммой.\",\n        (27, 2): \"Дай последовательность меток и конкретную метку. Попроси посчитать точки с этой меткой.\",\n        (27, 3): \"Дай расстояния от медоида до точек кластера. Попроси найти максимальное расстояние.\",\n    }\n    examples = {\n        (5, 0): \"Переведите число {source_number} из {source_system} системы в {target_system}. Запишите только результат.\",\n        (5, 1): \"Для N={n} определите ветку алгоритма по последнему биту двоичной записи: 0 или 1?\",\n        (5, 2): \"К двоичной строке {binary} припишите справа {suffix}. Какая строка получится?\",\n        (5, 3): \"Среди целых N от {start} до {limit} найдите наибольшее, для которого {expression} < {boundary}.\",\n        (14, 0): \"Число {n} переводят в систему с основанием {base}. Чему равен остаток от первого деления?\",\n        (14, 1): \"Цифра {digit} имеет числовое значение {value}. Является ли это значение чётным?\",\n        (14, 2): \"При переводе числа остатки получались в порядке: {remainders}. Последнее ненулевое частное — {last_quotient}. Запишите итоговую запись числа.\",\n        (27, 0): \"Даны точки {points}. Внутри групп расстояние не больше {within_distance}, между группами — не меньше {between_min}. Сколько кластеров выделяется?\",\n        (27, 1): \"Суммы расстояний до остальных точек: {sums}. Какая точка является медоидом?\",\n        (27, 2): \"Метки точек: {labels}. Сколько точек имеет метку {target}?\",\n        (27, 3): \"Расстояния от медоида: {distances}. Найдите максимальное расстояние.\",\n    }\n    placeholders = \", \".join(\"{\" + name + \"}\" for name in placeholders_by_operation[key])\n    preview = \", \".join(f\"{name}={value}\" for name, value in fields.items())\n    allowed_constants = \" Разрешены цифры 0 и 1 как названия веток.\" if key == (5, 1) else \"\"\n    return f\"\"\"\nТы — опытный учитель информатики, готовящий ученика к КЕГЭ. Создай ОДНУ короткую диагностическую задачу, похожую на нормальное упражнение на уроке или в тренажёре ЕГЭ.\n\nНавык: {skill_id}.\nПедагогическая семья: {families[key]}\nПример хорошего стиля: {examples[key]}\n\nPython уже создал и проверил данные: {preview}.\n\nОбязательные правила:\n- используй каждый плейсхолдер ровно один раз: {placeholders};\n- не добавляй числовых данных от себя;{allowed_constants}\n- не меняй математическую операцию и не добавляй второй шаг;\n- вопрос должен быть понятен без знания устройства Tutor;\n- используй обычную терминологию школьной информатики и КЕГЭ;\n- не используй мета-слова «значимые элементы», «показатель», «в рамках алгоритма», «представь, что у нас»;\n- не сообщай ответ и не объясняй решение;\n- длина до 260 символов, один явный вопрос.\n\nРанее показанные формулировки — не повторяй их близко:\n{previous or 'нет'}\n\nВерни только JSON:\n{{\"prompt_template\": \"...\"}}.\n\"\"\".strip()\n'''
prompts.write_text(text[:start] + new_func, encoding='utf-8')

diagnostics = Path('src/ai_engine/diagnostics.py')
